shaders/common/vertex.vert:
precision mediump float;
precision mediump int;

uniform mat4 modelViewMatrix; // optional
uniform mat4 projectionMatrix; // optional

attribute mediump vec3 position;
attribute mediump vec2 uv;

varying mediump vec2 vUv;

void main() {
	vUv = vec2( uv.x, uv.y);
	gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}

shaders/effects/pulseGradient.vert:
precision mediump float;
precision mediump int;

uniform mat4 modelViewMatrix; // optional
uniform mat4 projectionMatrix; // optional

attribute mediump vec3 position;
attribute mediump vec2 uv;

varying highp vec2 vUv;
varying mediump vec2 noiseUVA;
varying mediump vec2 noiseUVB;
varying mediump vec2 noiseUVC;

uniform highp float noiseTime;
uniform mediump vec2 randomOffset;

void main() {
	vUv = vec2( uv.x, uv.y);

	noiseUVA = uv*1.93 + randomOffset;// * 3.0;
	noiseUVB = uv*1.77 + randomOffset;// * 4.0 + noiseTime*2.9;
	noiseUVC = uv*1.55 - randomOffset;// * 2.3 - noiseTime*4.1;

	gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}

shaders/effects/emboss.vert:
precision mediump float;
precision mediump int;
uniform mediump mat4 modelViewMatrix; // optional
uniform mediump mat4 projectionMatrix; // optional
attribute mediump vec3 position;
attribute mediump vec2 uv;

varying mediump vec2 vUv;

varying mediump vec2 vUvm1m1;
varying mediump vec2 vUvm0m1;
// varying mediump vec2 vUvp1m1;
varying mediump vec2 vUvm1m0;
#define vUvm0m0 vUv
varying mediump vec2 vUvp1m0;
// varying mediump vec2 vUvm1p1;
varying mediump vec2 vUvm0p1;
varying mediump vec2 vUvp1p1;

uniform vec2 px1;

void main() {
    vUv = uv;

    vUvm1m1 = uv+vec2(-px1.x,-px1.y);
	vUvm1m0 = uv+vec2(-px1.x,0);
	// vUvm1p1 = uv+vec2(-px1.x,px1.y);

	vUvm0m1 = uv+vec2(0,-px1.y);
	// vUv00 =  uv;
	vUvm0p1 = uv+vec2(0,px1.y);

	// vUvp1m1 = uv+vec2(px1.x,-px1.y);
	vUvp1m0 = uv+vec2(px1.x,0);
	vUvp1p1 = uv+vec2(px1.x,px1.y);

	gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}

