// #include <common>
		// #include <color_pars_vertex>
		// #include <fog_pars_vertex>
		// #include <logdepthbuf_pars_vertex>
		// #include <clipping_planes_pars_vertex>

precision mediump float;
precision mediump int;

uniform mat4 modelViewMatrix; // optional
uniform mat4 projectionMatrix; // optional
attribute mediump vec3 position;
attribute mediump vec2 uv;

uniform float lineWidth;
uniform float ratio;
// #define aspect ratio
uniform vec2 resolution;
// #define ratio vec2(1.0,1.0)
// #define linewidth 0.01
uniform float pixelRatio;


attribute vec3 instanceStart;
attribute vec3 instanceEnd;

// attribute vec3 instanceColorStart;
// attribute vec3 instanceColorEnd;

varying vec2 vUv;

// #ifdef USE_DASH

// 	uniform float dashScale;
	attribute float instanceDistanceStart;
	attribute float instanceDistanceEnd;


	uniform mediump float pulseTime;
	uniform lowp float pulseDepth;

	uniform lowp float strokeInteractive;
	uniform lowp float strokeInteractivePulse;
	uniform lowp float strokeInteractiveDistance;
	uniform lowp vec2 mousePos;


// #endif
varying float vLineDistance;
varying vec2 vDir;

varying float vAngle;


void trimSegment( const in vec4 start, inout vec4 end ) {

	// trim end segment so it terminates between the camera plane and the near plane

	// conservative estimate of the near plane
	float a = projectionMatrix[ 2 ][ 2 ]; // 3nd entry in 3th column
	float b = projectionMatrix[ 3 ][ 2 ]; // 3nd entry in 4th column
	float nearEstimate = - 0.5 * b / a;

	float alpha = ( nearEstimate - start.z ) / ( end.z - start.z );

	end.xyz = mix( start.xyz, end.xyz, alpha );

}

void main() {

	// #ifdef USE_COLOR

	// 	vColor.xyz = ( position.y < 0.5 ) ? instanceColorStart : instanceColorEnd;

	// #endif

	// #ifdef USE_DASH

		vLineDistance = ( position.y < 0.5 ) ?  instanceDistanceStart : instanceDistanceEnd;

	// #endif

	float aspect = ratio; //pow(ratio, 0.66);
	// ratioratio.x / ratio.y;

	vUv = uv;

	// camera space
	vec4 start = modelViewMatrix * vec4( vec3(instanceStart.xy,0), 1.0 );
	vec4 end = modelViewMatrix * vec4( vec3(instanceEnd.xy,0), 1.0 );


			float endOfLine = 1.0;
	if (instanceStart.z+instanceEnd.z>0.0) {
				start.z = 0.0;
				end.z = 0.0;
				endOfLine = 0.0;
				// aspect = 0.0;
				// end = start;
				// start.xy = end.xy + normalize(end.xy-start.xy)*0.1;
			}


	// special case for perspective projection, and segments that terminate either in, or behind, the camera plane
	// clearly the gpu firmware has a way of addressing this issue when projecting into ndc space
	// but we need to perform ndc-space calculations in the shader, so we must address this issue directly
	// perhaps there is a more elegant solution -- WestLangley

	// bool perspective = ( projectionMatrix[ 2 ][ 3 ] == - 1.0 ); // 4th entry in the 3rd column

	// if ( perspective ) {

	// 	if ( start.z < 0.0 && end.z >= 0.0 ) {

	// 		trimSegment( start, end );

	// 	} else if ( end.z < 0.0 && start.z >= 0.0 ) {

	// 		trimSegment( end, start );

	// 	}

	// }

	// clip space
	vec4 clipStart = projectionMatrix * start;
	vec4 clipEnd = projectionMatrix * end;

	// ndc space
	highp vec2 ndcStart = clipStart.xy / clipStart.w;
	highp vec2 ndcEnd = clipEnd.xy / clipEnd.w;

	// direction
	vec2 dir = ndcEnd - ndcStart;


	// account for clip-space aspect ratio
	dir *= resolution;
	dir = normalize( dir );

	vec2 cDir = normalize(clipEnd.xy-clipStart.xy);
	vAngle = atan(cDir.y, cDir.x);

	// perpendicular to dir
	vec2 offset = vec2( dir.y, - dir.x );


	// undo aspect ratio adjustment
	// dir /= ratio;
	offset.x *= aspect;

	// sign flip
	if ( position.x < 0.0 ) offset *= - 1.0;

	// endcaps
	if ( position.y < 0.0 ) {

		offset += - dir;

	} else if ( position.y > 1.0 ) {

		offset += dir;

	}

	// adjust for linewidth
	offset *= lineWidth; // * vec2(pow(ratio, 0.66), 1.0); // / vec2(1.0, ratio);


	vec4 clip = ( position.y < 0.5 ) ? clipStart : clipEnd;


	lowp vec2 cUv = (clip.xy/clip.w) * 1.0;
	lowp float dst = pow(max(strokeInteractiveDistance-distance( cUv, mousePos),0.0)/strokeInteractiveDistance, 4.0-strokeInteractiveDistance*2.0);


	dst *= mix(1.0, (sin(pulseTime*2.0+dst*9.424778)*0.5+0.5), strokeInteractivePulse);

	float pulsePc = (sin(pulseTime)+1.0);
	offset *= 1.0 + dst*strokeInteractive*5.0 + pulsePc * pulseDepth;



	// clip.xy += dst * normalize(cUv)*resolution.x * (sin(pulseTime)+1.0) * pulseDepth;

	// adjust for clip-space to screen-space conversion // maybe ratio should be based on viewport ...
	// offset.y *= ratio;
	// offset *= vec2(pow(ratio, 0.5), 1.0);

	// offset /= (resolution);

	// offset.x *= resolution.x / 512.0;
	// offset.y *= resolution.y / 512.0;

	// float res = sqrt(resolution.x * resolution.x + resolution.y * resolution.y ) / 3200.0;

	// offset *= pow(res,0.);

	// offset *= pow(ratio,0.5);
	// if (ratio < 1.25) offset *= ratio;
	// offset *= pow(ratio*2.0, 10.0);
	// offset /= 3.0/pixelRatio;

	// select end

	// back to clip space
	// offset *= clip.w;
	offset *= 1080.0 * endOfLine;



	clip.xy += offset;

	gl_Position = clip;
	// vDir = dir;


	vDir = normalize(offset);


	vec4 mvPosition = ( position.y < 0.5 ) ? start : end; // this is an approximation

	// #include <logdepthbuf_vertex>
	// #include <clipping_planes_vertex>
	// #include <fog_vertex>

}

