shaders/effects/noise.vert:
precision mediump float;
precision mediump int;

uniform mat4 modelViewMatrix; // optional
uniform mat4 projectionMatrix; // optional

attribute mediump vec3 position;
attribute mediump vec2 uv;

varying mediump vec2 vUv;

varying highp vec2 noiseUv;
uniform highp vec2 randomOffset;
uniform highp vec2 resolution;

#if COLORED

varying highp vec2 noiseUv2;
varying highp vec2 noiseUv3;

#endif

void main() {
    highp vec2 ratio = normalize(resolution);
    highp float rescale = max(resolution.x, resolution.y) / 1280.0;
    vUv = vec2( uv.x, uv.y);
    noiseUv = (uv-0.5)*ratio*mat2(cos(randomOffset.y*6.0), sin(randomOffset.y*6.0), -sin(randomOffset.y*6.0), cos(randomOffset.y*6.0))*0.5*rescale + 0.5 + randomOffset;

   	#if COLORED
    noiseUv2 = (uv-0.5)*ratio*mat2(cos(randomOffset.x*6.0), sin(randomOffset.x*6.0), -sin(randomOffset.x*6.0), cos(randomOffset.x*6.0))*0.5*rescale*0.95 + 0.5 + randomOffset;
    noiseUv3 = (uv-0.5)*ratio*mat2(cos(randomOffset.x*-77.0), sin(randomOffset.x*-77.0), -sin(randomOffset.x*-77.0), cos(randomOffset.x*-77.0))*0.5*rescale*0.9 + 0.5 - randomOffset.yx;

   	#endif


    gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}

shaders/effects/pulseGradient3.frag:
precision mediump float;
precision mediump int;

varying highp vec2 vUv;
varying mediump vec2 noiseUVA;
varying mediump vec2 noiseUVB;
varying mediump vec2 noiseUVC;

uniform highp vec2 resolution;
uniform highp float pulseTime;
uniform highp float gradientTime;

uniform mediump float alpha;
uniform mediump float displacement;
uniform mediump float displacementStroke;
uniform highp float gradientMin;
uniform highp float gradientMax;
uniform mediump float noiseA;
uniform mediump float noiseB;
uniform highp float noiseTime;
uniform mediump vec2 randomOffset;

// uniform lowp sampler2D tForces;
// uniform lowp float forcesAlpha;

uniform lowp vec3 colorA;
uniform lowp vec3 colorB;
uniform lowp vec3 colorC;

uniform lowp vec3 fillColor;
uniform lowp float fillAlpha;


uniform mediump sampler2D tNoise;

void main() {

    mediump float noiseav = texture2D(tNoise, noiseUVA ).r;
    mediump float noisebv = texture2D(tNoise, noiseUVB ).r;
    mediump float noisecv = texture2D(tNoise, noiseUVC ).r;

    // float noiseav =  0.5;
    // float noisebv = 0.5;
    // float noisecv = 0.5;


    highp vec2 nuv = (vUv - 0.5) * normalize(resolution/max(resolution.x,resolution.y)) * vec2(1.15,1.0) + 0.5;
    highp float dst = distance(nuv, vec2(0.5)) * 2.0;

    highp float numGradient = (sin(dot(vec2(pulseTime*2.0,dst), vec2(0.5)))*0.5+0.5)*(gradientMax-gradientMin) + gradientMin;

    highp float gradient = sin(dst*6.1416*numGradient + gradientTime*0.22)*0.5+0.5;
    // float gradient = cnoise(vec2(dst*numGradient,gradientTime*1.19))*0.5+0.5;
    // gradient = mix(gradient,cnoise(vec2(dst*numGradient,gradientTime*2.19))*0.5+0.5,0.1);

    // gl_FragColor.rgb = vec3(cnoise(vec2(dst*numGradient,gradientTime*2.19))*0.5+0.5);
    // gl_FragColor.rgb = vec3(texture2D(tNoise, vec2(dst*numGradient,gradientTime*2.19)*0.002));
    // gl_FragColor.a = 1.0;

    // dst += gradientTime;
    highp float pulsePc = cos(dst*6.1416*numGradient + gradientTime)*0.5+0.5;


    // float noiseav = texture2D(tNoise, vUv*1.93 + randomOffset * 3.0).r;
    // float noisebv = texture2D(tNoise, vUv*1.77 + randomOffset * 4.0 + noiseTime*2.9).r;
    // float noisecv = texture2D(tNoise, vUv*1.55 - randomOffset * 2.3 - noiseTime*4.1 ).r;

    noiseav = pow(noiseav,3.0)*sign(noiseav*2.0-1.0)*2.0-0.7;
    noisebv = pow(noisebv,3.0)*sign(noisebv*2.0-1.0)*2.0-0.7;
    noisecv = pow(noisecv,3.0)*sign(noisecv*2.0-1.0)*2.0-0.7;

    // noiseav = (random(vUv*101.0+randomOffset))*2.0-1.0;
    // noisebv = (gold_noise(vUv*91.0+randomOffset, noiseTime*2.9))*2.0-1.0;
    // noisecv = (gold_noise(vUv*78.0-randomOffset, -noiseTime*4.1))*2.0-1.0;

    gradient += noisebv*0.1*noiseB;
    pulsePc += noisecv*0.1*noiseB;


    // vec3 col = mix(vec3(1.0), vec3(0.9,0.33,0.1), gradient);
    // col = mix(col, vec3(0.1,0.33,0.9), pulsePc);

    // vec3 col = mix(mix(colorA, colorB, max(1.0-gradient,0.0) ), colorB, clamp(pulsePc-gradient,0.0,1.0) ); //*gradient + colorB * pulsePc;
    mediump vec3 col = colorA * gradient + colorB * pulsePc;

    col = mix(col, colorC, pow(1.0-clamp(gradient+pulsePc,0.0,1.0),0.75) );

    col += noiseav*0.1*noiseA;
    col = clamp(col, vec3(0.0), vec3(1.0));

    // gl_FragColor = vec4(col, 1.0);


    // gl_FragColor = mix(vec4(1.0),mix(gl_FragColor, texture2D(tForces, vUv), forcesAlpha),alpha);

    gl_FragColor.rgb = mix(vec3(1.0),mix(col,fillColor,fillAlpha),alpha);
    gl_FragColor.a = 1.0;

    // gl_FragColor.rgb = vec3(pulsePc);


}

