precision mediump float;
precision mediump int;

varying mediump vec2 vUv;
varying mediump vec2 vUvm1m1;
varying mediump vec2 vUvm0m1;
// varying mediump vec2 vUvp1m1;
varying mediump vec2 vUvm1m0;
#define vUvm0m0 vUv
varying mediump vec2 vUvp1m0;
// varying mediump vec2 vUvm1p1;
varying mediump vec2 vUvm0p1;
varying mediump vec2 vUvp1p1;

uniform mediump sampler2D tDiffuse;

uniform mediump float embossAlpha;


void main() {
 	  vec3 colm1m1 = texture2D(tDiffuse, vUvm1m1).rgb;
    vec3 colm10 = texture2D(tDiffuse, vUvm1m0).rgb;
    // vec3 colm1p1 = texture2D(tDiffuse, vUvm1p1);
    vec3 col0m1 = texture2D(tDiffuse, vUvm0m1).rgb;
    vec3 col00 = texture2D(tDiffuse, vUvm0m0).rgb;
    vec3 col0p1 = texture2D(tDiffuse, vUvm0p1).rgb;
    // vec3 colp1m1 = texture2D(tDiffuse, vUvp1m1);
    vec3 colp10 = texture2D(tDiffuse, vUvp1m0).rgb;
    vec3 colp1p1 = texture2D(tDiffuse, vUvp1p1).rgb;

    vec3 total = 
      colm1m1 * -2.0 +
      colm10 * -1.0 +
      col0m1 * -1.0 +
      col00 + 
