uniform sampler2D tNoise;

// uniform lowp float noiseA;
// uniform lowp float noiseB;
// uniform lowp float noiseC;
uniform lowp float noiseD;
uniform lowp float noiseE;
// uniform lowp float noiseF;
// uniform lowp float noiseG;
// uniform lowp float noiseH;

uniform lowp float radial;
uniform lowp float colorA;
uniform lowp float colorB;

uniform lowp float alpha;

#define safepow(value,expv) pow(abs(value), expv)


void main() {

    mediump vec2 nuv = (vUv-0.5);

    // float noiseBVal = (texture2D(tNoise, vUv).r)*1.3;
    float noisev = texture2D(tNoise, vUv).r*noiseE;

    float grid4 = mod(vUv.x*resolution.x,6.0) + mod(vUv.y*resolution.y,6.0);
    // col *= grid4*noiseC*1.0 + 1.0-noiseC;
    nuv = nuv*(1.0-0.05*noiseD)+ grid4/resolution * noiseD * 4.0 *  min(nuv*8.0,vec2(1.0));
    nuv += noisev/resolution;


    float dst = length(nuv);
    float angle = atan(nuv.y, nuv.x);
    vec2 ruv = vec2(cos(angle+0.1)*dst, sin(angle+0.1)*dst);
    vec2 ruv2 = vec2(cos(angle-0.55)*dst, sin(angle-0.55)*dst);

    // angle += (noiseBVal*2.0-2.0) * 0.01*noiseB;

    //crosshatch rotated grid
    // float xgrid = texture2D(tNoise, vec2(0.5,ruv.y)).r;
    // float ygrid = texture2D(tNoise, vec2(ruv.x,0.5)).r;
    // col = vec3(ygrid*xgrid);

    // dst += pow( max(xgrid*ygrid,0.0),2.0)*0.01*noiseF;

    dst = pow(dst, 1.0-radial*0.2)*(1.0-radial*0.2);

    dst *= 1.0 + (noisev) * 0.4 * noiseE;

    float redDst = pow(dst,1.0-colorA*0.1);
    float blueDst = pow(dst,1.0-colorA*0.15);
    float greenDst = pow(dst,1.0-colorA*0.12);

    vec2 redUV = vec2( cos(angle)*redDst, sin(angle)*redDst) + 0.5;
    vec2 blueUV = vec2( cos(angle)*blueDst, sin(angle)*blueDst) + 0.5;
    vec2 greenUV = vec2( cos(angle)*greenDst, sin(angle)*greenDst) + 0.5;

    float grid2 = mod(vUv.x*resolution.x, 4.0 )+mod(vUv.y*resolution.y, 4.0) > 2.0 ? 1.0 : -1.0;
    redUV.x += grid2*0.005*colorB;
    greenUV.y += grid2*0.005*colorB;
    blueUV.xy -= grid2*0.005*colorB;


    vec3 col = vec3(
        texture2D(tDiffuse, redUV).r,
        texture2D(tDiffuse, greenUV).g,
        texture2D(tDiffuse, blueUV).b);

    // vec3 lastCol = vec3(
    //     texture2D(tLast, redUV).r,
    //     texture2D(tLast, greenUV).g,
    //     texture2D(tLast, blueUV).b
    // );
    // vec3 diff = clamp((lastCol-col),-1.0,1.0) * 100.0;// * pow(texture2D(tNoise, vUv+randomOffset).r,1.0+noiseH*20.0) * noiseG;

    // diff = diff * noiseG + diff * pow(texture2D(tNoise, vUv+randomOffset).r,10.0) * noiseH;

    // col += diff;

    //smaller grid, rotated
    // float grid = mod(vUv.x*resolution.x, 5.0 )+mod(vUv.y*resolution.y, 5.0) > 1.0 ? 1.0 : 0.0;
    // col *= grid*noiseA*1.0 + 1.0-noiseA;

    //larger grid
    // float grid3 = 1.0-(step(mod(vUv.x*resolution.x,7.0),1.0) + step(mod(vUv.y*resolution.y,7.0),1.0));
    // col *= grid3*noiseC*1.0 + 1.0-noiseC;

    // col += noiseC*0.05;
    // col = mix(col, vec3(noiseBVal), noiseB*0.25);

    // col = mix(col, col * pow( max(xgrid*ygrid,0.0),0.3), noiseF*0.1);



    gl_FragColor = vec4(col , 1.0);

}

