precision mediump float;
precision mediump int;

varying mediump vec2 vUv;

uniform lowp vec2 size;
uniform lowp vec2 resolution;
uniform lowp float alpha;
uniform lowp vec2 ratio;


//---------------------------------------------------------
// draw rectangle frame with rounded edges
//---------------------------------------------------------
mediump float roundedFrame (vec2 pos, vec2 size, float radius, float thickness)
{
	vec2 nuv = (vUv-0.5) / normalize(resolution)*vec2(1.25,1.0) + 0.5;
  mediump float d = length(max(abs(nuv - pos),size) - size) - radius;
  return smoothstep(0.6, 0.55, abs(d / thickness) * 5.0); // - step(abs(d / thickness) * 5.0, 0.45);
}


