  vec2 nuv = pow(abs(vUv-0.5)*2.0,ratio*3.0)/2.0 + 0.5;
  float cornerDst = distance(nuv, vec2(0.9, 0.9));

  cornerDst = cimap(cornerDst, 0.1, 0.105, 1.0, 0.0);
  if (nuv.y < 1.0 && nuv.x < 0.91) cornerDst = 1.0;
  if (nuv.x < 1.0 && nuv.y < 0.91) cornerDst = 1.0;

	// mediump float box = roundedFrame(
